namespace sv_cc03815473324222aa929e5563202633.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// Interactive components subscribe to OnChange to re-render when the theme is updated.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Theme or AccentColor changes.
    /// Subscribers should call StateHasChanged().
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island that lives inside the static layout.
   Because it has its own @rendermode, it joins the page's circuit
   and shares the same scoped ThemeService as every other interactive component. *@

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<span class="badge rounded-pill"
      style="background-color: @ThemeSvc.AccentColor; color: white;">
    @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            var isActive = ThemeSvc.Theme == mode;
            <button type="button"
                    class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeSvc.Theme = mode">
                @mode
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accentPicker">Accent Color</label>
    <input id="accentPicker"
           type="color"
           class="form-control form-control-color"
           value="@ThemeSvc.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @ThemeSvc.AccentColor !important;">
    <strong>Preview:</strong> Theme is <em>@ThemeSvc.Theme</em>,
    accent is <span style="color: @ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>.
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

